'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seeds=[['Vodafone / VOIS','https://jobs.vodafone.com/careers?filter_country=Egypt','eightfold'],['Siemens','https://jobs.siemens.com/en_US/externaljobs','avature'],['Valeo','https://valeo.wd3.myworkdayjobs.com/en-US/valeo_jobs','workday'],['Microsoft','https://apply.careers.microsoft.com/careers','microsoft'],['Fawry','https://www.fawry.com/jobs/','jsonld']];
const defaults={mode:'preview',sources:seeds.map((x,i)=>({id:i+1,name:x[0],url:x[1],kind:x[2],enabled:0,approved:0,status:'Needs review',baseline:0})),jobs:[],runs:[],outbox:[],smtp_ready:false,heartbeat:null,settings:{interval:30,email:'',email_enabled:false,paused:false,keywords:'python,software,backend,machine learning,computer vision,deep learning,mlops,data scientist,artificial intelligence',locations:'egypt,cairo,giza',min_score:3}};
let state=structuredClone(defaults),view='overview',search='',filter='all',loaded=false;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',6000)}
function persist(){try{localStorage.setItem('jobhunter-preview-v1',JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes will not persist.')}}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-Job-Hunter':'1'},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json()}catch{throw Error('Server returned an unexpected response')}if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Please check your entries');return d}
async function load(){try{state=await api('state')}catch(e){if(!loaded){try{state=JSON.parse(localStorage.getItem('jobhunter-preview-v1'))||structuredClone(defaults)}catch{state=structuredClone(defaults)}state.mode='preview'}else if(state.mode==='server'){toast('Connection lost. Displaying the last received state.');return}}loaded=true;$('#preview-banner').hidden=state.mode!=='preview';render()}
const preview=()=>state.mode==='preview';
const logo=s=>{let k=s.toLowerCase().split(/[ /]/)[0];return `<span class="logo ${['vodafone','siemens','valeo','microsoft','fawry'].includes(k)?k:'other'}">${esc(k==='microsoft'?'▦':k==='vodafone'?'v':k==='siemens'?'S':k==='valeo'?'V':k==='fawry'?'f':s[0].toUpperCase())}</span>`};
const date=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not yet';
const safeURL=u=>{try{const x=new URL(u);return x.protocol==='https:'?esc(x.href):'#'}catch{return '#'}};
function heading(title,subtitle,action=true){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action?'<button class="primary" data-action="add">＋ <span>Add company</span></button>':''}</div>`}
function empty(saved=false){return `<div class="empty"><div class="empty-icon">${saved?'♡':'⌕'}</div><h3>${saved?'Keep your next move close.':'Your next opportunity goes here.'}</h3><p>${saved?'Save interesting roles from your job feed and come back when you’re ready.':'Once monitoring is connected, new matching jobs will appear here. No noise. No repeat alerts.'}</p><button class="secondary" data-view="${saved?'jobs':'companies'}">${saved?'Explore job feed':'Set up your companies'} →</button></div>`}
function jobcards(jobs){if(!jobs.length)return empty(view==='saved');return jobs.map(j=>`<article class="jobcard"><div class="jobtop">${logo(j.company)}<div><h3>${esc(j.title)}</h3><div class="jobmeta">${esc(j.company)} · ${esc(j.location)}</div></div><button data-save="${j.id}" aria-label="${j.saved?'Unsave':'Save'} job">${j.saved?'♥':'♡'}</button></div><div class="jobtags"><span>${esc(j.employment)}</span><span>Match score ${j.score}</span><span>Published: ${esc(j.published||'Not provided')}</span></div><details><summary class="jobmeta">Why this matches & description</summary><p class="jobdesc">${esc((()=>{try{return JSON.parse(j.reasons).join(' · ')}catch{return ''}})())}</p><p class="jobdesc">${esc(j.description)}</p></details><div class="jobfooter"><span>Detected ${date(j.detected)}</span><a href="${safeURL(j.url)}" target="_blank" rel="noopener noreferrer">View opportunity →</a></div></article>`).join('')}
function overview(){const matches=state.jobs.filter(j=>j.score>=state.settings.min_score),active=state.sources.filter(s=>s.enabled).length;const running=state.heartbeat&&Date.now()-new Date(state.heartbeat)<180000;return heading('Your next move starts here.','A little less searching. A lot more opportunity.')+`<section class="hero"><div class="hero-text"><p class="eyebrow">STAY ONE STEP AHEAD</p><h2>The right role.<br>On your radar, sooner.</h2><p>Engineering & AI opportunities, with Egypt in focus.</p><button class="textbutton hero-link" data-view="alerts">Fine-tune your preferences →</button></div><div class="radar" aria-hidden="true"></div></section><div class="stats"><div class="stat"><div class="stat-top">Matching opportunities<span class="stat-icon">→</span></div><div class="stat-value">${matches.length}</div><div class="stat-foot">From official careers pages</div></div><div class="stat"><div class="stat-top">Companies on your radar<span class="stat-icon">▦</span></div><div class="stat-value">${state.sources.length}</div><div class="stat-foot">${active} enabled for monitoring</div></div><div class="stat"><div class="stat-top">Check interval<span class="stat-icon">◷</span></div><div class="stat-value">${state.settings.interval}<span style="font-size:13px;color:#a0a5b1;margin-left:5px">sec</span></div><div class="stat-foot">Target · subject to source limits</div></div><div class="stat"><div class="stat-top">Email alerts<span class="stat-icon">✉</span></div><div class="stat-value" style="font-size:22px">${state.smtp_ready&&state.settings.email_enabled?'Enabled':'Not connected'}</div><div class="stat-foot">${state.smtp_ready?'SMTP configured':'Connect your email to get started'}</div></div></div><div class="columns"><section class="panel"><div class="panel-head"><div><h3>Your opportunity feed</h3><p>The roles worth your attention.</p></div><button class="textbutton" data-view="jobs">View all →</button></div><div class="tabs"><button class="selected" data-view="jobs">All matches</button><button data-filter="early">Early careers</button><button data-view="saved">Saved</button></div>${jobcards(matches.slice(0,4))}<div class="microbar"><span>◷ ${running?'Worker connected':'Worker not connected'}</span><button class="textbutton" data-action="check">Check now ↻</button></div></section><aside><section class="panel"><div class="panel-head"><h3>On your radar</h3><button class="textbutton" data-view="companies">Manage</button></div><div class="companies-mini">${state.sources.slice(0,5).map(s=>`<div class="company-mini">${logo(s.name)}<div><strong>${esc(s.name)}</strong><small>${s.enabled?'Monitoring enabled':s.kind==='eightfold'?'Access validation needed':'Ready for source review'}</small></div><span class="dot ${s.enabled?'green':''}"></span></div>`).join('')}</div></section><div class="small-panel"><h3>✉ Make your inbox work for you.</h3><p>Get the job title, location and application link. Only when there’s something new.</p><button class="textbutton" data-view="alerts">Set up email alerts →</button></div></aside></div>`}
function companies(){return heading('Companies on your radar.','Your watchlist, your rules. Add the places you’d love to work.')+`<div class="panel"><div class="panel-head"><h3>Company watchlist <span class="status-pill">${state.sources.length} companies</span></h3><span class="status-pill">${state.settings.interval}s target interval</span></div><div class="tablewrap"><table><thead><tr><th>COMPANY</th><th>MONITORING STATUS</th><th>LAST CHECK</th><th>ACTIONS</th></tr></thead><tbody>${state.sources.map(s=>`<tr><td><div class="company-cell">${logo(s.name)}<div><strong>${esc(s.name)}</strong><small>${esc(s.kind==='workday'?'Workday job board':s.kind==='jsonld'?'Structured job data':s.kind==='microsoft'?'Microsoft careers':'Official careers')}</small></div></div></td><td><span class="status-pill ${s.enabled?'good':'warn'}">${esc(s.enabled?s.status||'Queued':s.kind==='eightfold'?'Needs adapter validation':'Paused · review required')}</span>${s.error?`<p class="source-error">${esc(s.error)}</p>`:''}</td><td style="color:#979ca8;font-size:11px">${date(s.last_check)}</td><td><div class="inline-actions"><a href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">Open →</a><button data-enable="${s.id}">${s.enabled?'Pause':'Enable'}</button></div></td></tr>`).join('')}</tbody></table></div></div><div class="hint">First scans establish a baseline without emailing existing vacancies. Enable a source only after reviewing its terms and permitted request frequency. Custom links require a compatible job board or structured data; a URL alone does not guarantee coverage.</div>`}
function jobs(){let list=state.jobs.filter(j=>(view!=='saved'||j.saved)&&(filter==='all'||filter==='early'&&/intern|junior|graduate|trainee|work experience/i.test(j.title)||filter==='matches'&&j.score>=state.settings.min_score)&&(`${j.title} ${j.company} ${j.description}`).toLowerCase().includes(search.toLowerCase()));return heading(view==='saved'?'Good opportunities, kept close.':'Find your next opportunity.',view==='saved'?'Your shortlist. Ready when you are.':'Search titles, companies and descriptions from your monitored sources.',false)+`<div class="panel"><div class="searchrow"><input id="job-search" aria-label="Search jobs" placeholder="Search roles, skills or companies…" value="${esc(search)}"><select id="job-filter" aria-label="Filter jobs"><option value="all" ${filter==='all'?'selected':''}>All discovered jobs</option><option value="matches" ${filter==='matches'?'selected':''}>Matching preferences</option><option value="early" ${filter==='early'?'selected':''}>Early careers</option></select></div><div id="job-results">${jobcards(list)}</div></div>`}
function alerts(){return heading('The right alerts. Your way.','Choose what matters. We’ll keep the rest quiet.',false)+`<form id="settings-form"><div class="forms"><section class="panel form-panel"><h3>✉ Email notifications</h3><p>New matching vacancies, delivered to your inbox.</p><label>Send alerts to<input name="email" type="email" value="${esc(state.settings.email)}" placeholder="you@example.com"></label><label class="checkbox"><input name="email_enabled" type="checkbox" ${state.settings.email_enabled?'checked':''}>Enable email alerts</label><div class="hint">${preview()?'Preview only: this saves your preference in this browser. To send email, deploy the app and configure SMTP on your server.':state.smtp_ready?'SMTP is configured. Send a test email to verify delivery.':'SMTP is not configured. Add SMTP_HOST, SMTP_USER, SMTP_PASSWORD and SMTP_FROM to the server environment.'}</div><button type="button" class="secondary" data-action="test-email">Send test email →</button><p style="font-size:10px;margin-top:15px">No inbox access needed. Your email password never goes into this form.</p></section><section class="panel form-panel"><h3>⌕ Search preferences</h3><p>We match descriptions too, not just exact job titles.</p><label>Skills & role keywords<textarea name="keywords">${esc(state.settings.keywords)}</textarea></label><label>Preferred locations<input name="locations" value="${esc(state.settings.locations)}"></label><label>Polling target<select name="interval">${[30,60,300,900,1800,3600].map(v=>`<option value="${v}" ${state.settings.interval===v?'selected':''}>${v<60?v+' seconds':v/60+' minutes'}</option>`).join('')}</select></label><label>Minimum match score<input name="min_score" type="number" min="0" max="10" value="${state.settings.min_score}"></label><label class="checkbox"><input name="paused" type="checkbox" ${state.settings.paused?'checked':''}>Pause all monitoring</label></section></div><div class="actionbar"><button class="primary" type="submit">Save preferences →</button><span class="subtitle">30 seconds is a target, not a delivery guarantee.</span></div></form><div class="panel" style="margin-top:25px"><div class="panel-head"><h3>Delivery activity</h3></div>${state.outbox.length?state.outbox.map(o=>`<div class="activity"><strong>${esc(o.title)}</strong> <span class="status-pill">${esc(o.state)}</span><br><small>${esc(o.error||'')}</small></div>`).join(''):'<div class="activity"><small>No email delivery attempts yet.</small></div>'}</div>`}
function deploy(){return heading('Take Job Hunter live.','The complete Python app runs on your server—even when your computer is off.',false)+`<div class="deploy-grid"><section class="panel form-panel"><p class="eyebrow">YOUR DEPLOYMENT CHECKLIST</p><h3>One server. A website. A quiet worker.</h3><div class="steps"><div class="step"><div><strong>Download the complete project</strong><p>Includes the website, FastAPI backend, SQLite, polling worker, tests and Docker deployment files.</p><a class="textbutton" href="job-hunter-source.zip" download>Download source ZIP ↓</a></div></div><div class="step"><div><strong>Choose an always-on Linux server</strong><p>Oracle Always Free is an option, subject to capacity and reclaim rules. Select only resources marked Always Free; do not rely on trial credits.</p></div></div><div class="step"><div><strong>Configure credentials securely</strong><p>Copy <code>.env.example</code> to <code>.env</code>, set a strong admin password and add your SMTP credentials. Never commit this file.</p></div></div><div class="step"><div><strong>Start the app and worker</strong><p>Run <code>docker compose up -d --build</code>. The web server and worker share a persistent SQLite volume.</p></div></div><div class="step"><div><strong>Verify, then enable sources</strong><p>Use an SSH tunnel or HTTPS reverse proxy, save your email, send a test and enable reviewed sources. The first scan is a silent baseline.</p></div></div></div><a class="secondary" href="DEPLOYMENT.md" download>Read full deployment instructions →</a></section><div><section class="panel form-panel"><h3>What’s running here?</h3><p>${preview()?'This hosted website is a browser preview. It does not run the Python worker or send emails. Your preview settings are stored only on this device.':'This is your Python-backed deployment. Check the worker heartbeat and source status before relying on alerts.'}</p><div class="hint">A browser refresh timer is not background monitoring. The included server worker performs checks independently of this website.</div><h3>About 30-second checks</h3><p>The worker supports a 30-second target. Scan duration, site policies and rate limits can make checks slower. Errors trigger backoff; restricted sources stop.</p><p>GitHub Actions cannot provide a 30-second schedule. Use it for tests, not the polling service.</p></section><section class="small-panel" style="margin-top:20px"><h3>Source coverage, honestly.</h3><p>Valeo, Siemens and Microsoft have source readers. Vodafone/VOIS and Fawry are included but access is not yet validated. Adding a careers link does not bypass website restrictions.</p></section></div></div>`}
function render(){document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#breadcrumb').textContent={overview:'Overview',jobs:'Job feed',saved:'Saved jobs',companies:'Companies',alerts:'Email & preferences',deploy:'Deployment'}[view];$('#feed-count').textContent=state.jobs.filter(j=>j.score>=state.settings.min_score).length;$('#main-content').innerHTML=({overview,companies,jobs,saved:jobs,alerts,deploy}[view])()}
async function action(fn){try{await fn()}catch(e){toast(e.message)}}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-view]');if(!el)return;if(el.dataset.view){view=el.dataset.view;render();window.scrollTo(0,0)}if(el.dataset.filter){filter=el.dataset.filter;view='jobs';render()}if(el.dataset.action==='add')$('#source-dialog').showModal();if(el.id==='close-dialog')$('#source-dialog').close();if(el.dataset.action==='check')action(async()=>{if(preview())return toast('Deploy the Python app to run checks. This preview does not contact careers websites.');toast((await api('check','POST')).message);await load()});if(el.dataset.action==='test-email')action(async()=>{if(preview())return toast('Email is not connected in this preview. Follow the deployment guide to enable delivery.');toast((await api('email/test','POST')).message)});if(el.dataset.enable)action(async()=>{let s=state.sources.find(s=>s.id===Number(el.dataset.enable));if(!s.enabled&&!confirm('Have you reviewed this careers site’s terms and confirmed that your selected polling frequency is permitted? Unsupported sources will report an error rather than bypass restrictions.'))return;if(preview()){s.enabled=Number(!s.enabled);s.approved=1;s.status='Preview only';persist();render();toast('Preview preference saved. Background monitoring requires deployment.')}else{await api('sources/'+s.id,'PUT',{enabled:!s.enabled,approved:true});await load()}});if(el.dataset.save)action(async()=>{if(preview()){let j=state.jobs.find(j=>j.id===Number(el.dataset.save));if(j)j.saved=!j.saved;persist();render()}else{await api('jobs/'+el.dataset.save+'/save','POST');await load()}})});
document.addEventListener('submit',e=>{if(e.target.id==='source-form'){e.preventDefault();action(async()=>{const data=Object.fromEntries(new FormData(e.target));const u=new URL(data.url);if(u.protocol!=='https:'||u.username||u.password)throw Error('Use a public HTTPS careers URL.');if(preview()){if(state.sources.some(s=>s.url===u.href))throw Error('This URL is already in your watchlist');state.sources.push({id:Math.max(...state.sources.map(s=>s.id))+1,name:data.name,url:u.href,kind:u.hostname.endsWith('.myworkdayjobs.com')?'workday':'jsonld',enabled:0,status:'Needs review'});persist()}else await api('sources','POST',data);$('#source-dialog').close();e.target.reset();view='companies';if(preview())render();else await load();toast('Company added. Review source compatibility before enabling.');})}if(e.target.id==='settings-form'){e.preventDefault();action(async()=>{const f=new FormData(e.target);const data={...state.settings,...Object.fromEntries(f),interval:Number(f.get('interval')),min_score:Number(f.get('min_score')),email_enabled:f.has('email_enabled'),paused:f.has('paused')};if(preview()){state.settings=data;persist();render()}else{await api('settings','PUT',data);await load()}toast(preview()?'Preferences saved in this browser. Email is not connected.':'Preferences saved')})}});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){search=e.target.value;let start=e.target.selectionStart;render();$('#job-search').focus();$('#job-search').setSelectionRange(start,start)}});document.addEventListener('change',e=>{if(e.target.id==='job-filter'){filter=e.target.value;render()}});
load();setInterval(()=>{if(!preview()&&!document.querySelector('input:focus,textarea:focus,select:focus')&&!$('#source-dialog').open)load()},30000);
